-- SINAGA shared content database
-- Generated from sinaga-share.sqlite

PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;

DROP TABLE IF EXISTS "account_session_locks";
CREATE TABLE "account_session_locks" ("user_id" integer not null, "session_id" varchar not null, "last_seen_at" datetime not null, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, primary key ("user_id"));

DROP TABLE IF EXISTS "activity_logs";
CREATE TABLE "activity_logs" ("id" integer primary key autoincrement not null, "user_id" integer, "article_id" integer, "action" varchar not null, "detail" varchar not null default '', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete set null, foreign key("article_id") references "articles"("id") on delete set null);

DROP TABLE IF EXISTS "articles";
CREATE TABLE "articles" ("id" integer primary key autoincrement not null, "author_id" integer, "category_id" integer, "title" varchar not null, "slug" varchar not null, "excerpt" varchar not null default (''), "body" text not null, "cover_image" varchar, "status" varchar not null default ('draft'), "revision_note" text, "published_at" datetime, "created_at" datetime, "updated_at" datetime, "author_name" varchar, "updated_by" integer, "updated_by_name" varchar, foreign key("category_id") references "categories"("id") on delete set null on update no action, foreign key("author_id") references "users"("id") on delete set null, foreign key("updated_by") references "users"("id") on delete set null);

DROP TABLE IF EXISTS "cache";
CREATE TABLE "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));

DROP TABLE IF EXISTS "cache_locks";
CREATE TABLE "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));

DROP TABLE IF EXISTS "categories";
CREATE TABLE "categories" ("id" integer primary key autoincrement not null, "name" varchar not null, "slug" varchar not null, "created_at" datetime, "updated_at" datetime);

DROP TABLE IF EXISTS "contact_messages";
CREATE TABLE "contact_messages" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "subject" varchar not null, "message" text not null, "read_at" datetime, "created_at" datetime, "updated_at" datetime);

DROP TABLE IF EXISTS "content_entries";
CREATE TABLE "content_entries" ("id" integer primary key autoincrement not null, "author_id" integer, "type" varchar not null, "title" varchar not null, "slug" varchar, "excerpt" varchar not null default '', "body" text, "image_path" varchar, "document_path" varchar, "location" varchar, "starts_at" datetime, "metadata" text, "published" tinyint(1) not null default '0', "sort_order" integer not null default '0', "created_at" datetime, "updated_at" datetime, "author_name" varchar, foreign key("author_id") references "users"("id") on delete set null);

DROP TABLE IF EXISTS "failed_jobs";
CREATE TABLE "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" varchar not null, "queue" varchar not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);

DROP TABLE IF EXISTS "job_batches";
CREATE TABLE "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));

DROP TABLE IF EXISTS "jobs";
CREATE TABLE "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);

DROP TABLE IF EXISTS "media_assets";
CREATE TABLE "media_assets" ("id" integer primary key autoincrement not null, "uploaded_by" integer, "path" varchar not null, "mime_type" varchar not null, "size" integer not null, "alt_text" varchar not null default '', "caption" varchar not null default '', "created_at" datetime, "updated_at" datetime, foreign key("uploaded_by") references "users"("id") on delete set null);

DROP TABLE IF EXISTS "migrations";
CREATE TABLE "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);

DROP TABLE IF EXISTS "password_reset_tokens";
CREATE TABLE "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));

DROP TABLE IF EXISTS "sessions";
CREATE TABLE "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));

DROP TABLE IF EXISTS "site_settings";
CREATE TABLE "site_settings" ("key" varchar not null, "value" text, "created_at" datetime, "updated_at" datetime, primary key ("key"));

DROP TABLE IF EXISTS "spmb_announcements";
CREATE TABLE "spmb_announcements" ("id" integer primary key autoincrement not null, "title" varchar not null, "body" text not null, "starts_at" datetime, "published" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime);

DROP TABLE IF EXISTS "spmb_contacts";
CREATE TABLE "spmb_contacts" ("id" integer primary key autoincrement not null, "name" varchar not null, "role" varchar, "phone" varchar not null, "office_hours" varchar, "note" text, "published" tinyint(1) not null default '0', "sort_order" integer not null default '0', "created_at" datetime, "updated_at" datetime);

DROP TABLE IF EXISTS "spmb_photos";
CREATE TABLE "spmb_photos" ("id" integer primary key autoincrement not null, "title" varchar not null, "caption" text, "image_path" varchar not null, "published" tinyint(1) not null default '0', "sort_order" integer not null default '0', "created_at" datetime, "updated_at" datetime);

DROP TABLE IF EXISTS "spmb_settings";
CREATE TABLE "spmb_settings" ("id" integer primary key autoincrement not null, "title" varchar not null default 'Penerimaan Murid Baru', "school_year" varchar, "introduction" text, "schedule" text, "requirements" text, "steps" text, "documents" text, "quota" integer, "fee_information" text, "registration_url" varchar, "poster_path" varchar, "published" tinyint(1) not null default '0', "created_at" datetime, "updated_at" datetime, "status" varchar not null default 'preparation');

DROP TABLE IF EXISTS "users";
CREATE TABLE "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "role" varchar not null default 'teacher', "active" tinyint(1) not null default '1', "username" varchar);

CREATE INDEX "account_session_locks_last_seen_at_index" on "account_session_locks" ("last_seen_at");
CREATE UNIQUE INDEX "account_session_locks_session_id_unique" on "account_session_locks" ("session_id");
CREATE INDEX "activity_logs_created_at_index" on "activity_logs" ("created_at");
CREATE INDEX "articles_published_at_index" on "articles" ("published_at");
CREATE UNIQUE INDEX "articles_slug_unique" on "articles" ("slug");
CREATE INDEX "articles_status_index" on "articles" ("status");
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE UNIQUE INDEX "categories_name_unique" on "categories" ("name");
CREATE UNIQUE INDEX "categories_slug_unique" on "categories" ("slug");
CREATE INDEX "content_entries_published_index" on "content_entries" ("published");
CREATE INDEX "content_entries_starts_at_index" on "content_entries" ("starts_at");
CREATE INDEX "content_entries_type_index" on "content_entries" ("type");
CREATE INDEX "content_entries_type_published_sort_order_index" on "content_entries" ("type", "published", "sort_order");
CREATE INDEX "failed_jobs_connection_queue_failed_at_index" on "failed_jobs" ("connection", "queue", "failed_at");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE UNIQUE INDEX "media_assets_path_unique" on "media_assets" ("path");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "spmb_announcements_published_index" on "spmb_announcements" ("published");
CREATE INDEX "spmb_contacts_published_index" on "spmb_contacts" ("published");
CREATE INDEX "spmb_photos_published_index" on "spmb_photos" ("published");
CREATE INDEX "spmb_settings_published_index" on "spmb_settings" ("published");
CREATE INDEX "users_active_index" on "users" ("active");
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE INDEX "users_role_index" on "users" ("role");
CREATE UNIQUE INDEX "users_username_unique" on "users" ("username");

COMMIT;
PRAGMA foreign_keys=ON;
